647	func (p int64InstProvider) histogramAggs(
648		name string,
649		cfg metric.Int64HistogramConfig,
650	) ([]aggregate.Measure[int64], error) {
651		boundaries := cfg.ExplicitBucketBoundaries()
652		aggError := AggregationExplicitBucketHistogram{Boundaries: boundaries}.err()
