659			Description: cfg.Description(),
660			Unit:        cfg.Unit(),
661			Kind:        InstrumentKindHistogram,
662			Scope:       p.scope,
663		}
664		measures, err := p.int64Resolver.HistogramAggregators(inst, boundaries)
665		return measures, errors.Join(aggError, err)
666	}
