307	// float64ObservableInstrument returns a new observable identified by the Instrument.
308	// It registers callbacks for each reader's pipeline.
309	func (m *meter) float64ObservableInstrument(
310		id Instrument,
311		callbacks []metric.Float64Callback,
312	) (float64Observable, error) {
313		key := instID{
314			Name:        id.Name,
315			Description: id.Description,
316			Unit:        id.Unit,
317			Kind:        id.Kind,
318		}
319		if m.int64ObservableInsts.HasKey(key) && len(callbacks) > 0 {
320			warnRepeatedObservableCallbacks(id)
321		}
322		return m.float64ObservableInsts.Lookup(key, func() (float64Observable, error) {
323			inst := newFloat64Observable(m, id.Kind, id.Name, id.Description, id.Unit)
324			for _, insert := range m.float64Resolver.inserters {
325				// Connect the measure functions for instruments in this pipeline with the
326				// callbacks for this pipeline.
327				in, err := insert.Instrument(id, insert.readerDefaultAggregation(id.Kind))
328				if err != nil {
329					return inst, err
330				}
331				// Drop aggregation
332				if len(in) == 0 {
333					inst.dropAggregation = true
334					continue
335				}
336				inst.appendMeasures(in)
337	
338				// Add the measures to the pipeline. It is required to maintain
339				// measures per pipeline to avoid calling the measure that
340				// is not part of the pipeline.
341				insert.pipeline.addFloat64Measure(inst.observableID, in)
342				for _, cback := range callbacks {
343					inst := float64Observer{measures: in}
344					fn := cback
345					insert.addCallback(func(ctx context.Context) error { return fn(ctx, inst) })
346				}
347			}
348			return inst, validateInstrumentName(id.Name)
349		})
350	}
