424	func validateInstrumentName(name string) error {
425		if name == "" {
426			return fmt.Errorf("%w: %s: is empty", ErrInstrumentName, name)
427		}
428		if len(name) > 255 {
429			return fmt.Errorf("%w: %s: longer than 255 characters", ErrInstrumentName, name)
430		}
431		if !isAlpha([]rune(name)[0]) {
432			return fmt.Errorf("%w: %s: must start with a letter", ErrInstrumentName, name)
433		}
434		if len(name) == 1 {
435			return nil
436		}
437		for _, c := range name[1:] {
438			if !isAlphanumeric(c) && c != '_' && c != '.' && c != '-' && c != '/' {
439				return fmt.Errorf("%w: %s: must only contain [A-Za-z0-9_.-/]", ErrInstrumentName, name)
440			}
441		}
442		return nil
443	}

