// defaultAttributesOption is a metric.InstrumentOption that specifies the
// attribute keys allowed by default for an instrument.
type defaultAttributesOption struct {
	// InstrumentOption is embedded so defaultAttributesOption satisfies the
	// metric.InstrumentOption interface. The embedded value is never used; the
	// SDK reads the configuration through the AllowedKeys method instead.
	metric.InstrumentOption

	keys []attribute.Key
}

// Experimental marks the option as experimental. It ensures the standard
// metric API skips the option instead of panicking, because
// defaultAttributesOption does not implement all the apply methods required by
// metric.InstrumentOption.
func (defaultAttributesOption) Experimental() {}

// AllowedKeys returns the attribute keys allowed by default for the instrument.
func (o defaultAttributesOption) AllowedKeys() []attribute.Key {
	return o.keys
}

// WithDefaultAttributes returns a [metric.InstrumentOption] that specifies
// which attribute keys are allowed by default for a metric instrument.
//
// When the returned option is passed during instrument creation, only
// attributes whose keys appear in keys are included in recorded data points.
// Any attribute whose key is not in keys is filtered out and treated as opt-in.
// Passing no keys results in all attributes being filtered out (an empty
// attribute set).
//
// When this option is not provided, no filtering occurs and all recorded
// attributes are retained.
//
// SDK users can override this per-instrument filtering by registering a View
// that matches the instrument; the View's attribute configuration takes
// precedence.
func WithDefaultAttributes(keys ...attribute.Key) metric.InstrumentOption {
	return defaultAttributesOption{keys: keys}
}
